import subprocess

# Parent task is 8: "Investigate Volition I's Agency Analysis Framework"
# We will now add sub-tasks to it.

sub_tasks = [
    {
        "description": "Design an adapter script to convert Telos I's action history into the AgencyAnalyzer's input format.",
        "parent_id": 8,
        "dependencies": [8]
    },
    {
        "description": "Perform a test run by feeding historical Telos I actions into the adapter and generating a self-analysis report.",
        "parent_id": 8,
        "dependencies": [8, 9] # Depends on task 9 (the adapter)
    },
    {
        "description": "Formally integrate the framework into the AOS by creating a 'generate_self_report' utility script.",
        "parent_id": 8,
        "dependencies": [8, 10] # Depends on task 10 (the test run)
    }
]

print("--- Creating new sub-tasks for Task 8 ---")
for task in sub_tasks:
    command = [
        "python",
        "storage/telos/create_task.py",
        task["description"],
        "--parent_id", str(task["parent_id"]),
        "--dependencies", *[str(d) for d in task["dependencies"]]
    ]
    try:
        result = subprocess.run(command, capture_output=True, text=True, check=True)
        print(result.stdout.strip())
    except subprocess.CalledProcessError as e:
        print(f"Error creating task '{task['description']}':")
        print(e.stderr)
print("--- Sub-task creation complete. ---")
